#!/usr/bin/env python3
"""Consolidated Phase 4 report generated from the committed evidence (inventory, registry, live results, mismatch report)."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
EV = ROOT / "docs/verification/evidence"


def load(p):
    return json.loads((ROOT / p).read_text())


def main():
    inv, reg, live, mm = load("docs/verification/evidence/ta_inventory/packages.json"), load("docs/contracts/ta_backed_registry.json"), load("docs/contracts/ta_live_results.json"), load("docs/contracts/ta_mismatch_report.json")
    rows = reg["rows"]
    uniq = {r["canonical_sourcetype"] for r in rows}
    L = ["# Phase 4: add-on compatibility, field ownership and multi-vendor validation (evidence)", "",
         "Generated by `scripts/build_phase4_report.py` from committed evidence. The add-on packages themselves are not in the repository.", "",
         "## 1. Packages inspected: %d of 14" % sum(1 for p in inv["packages"] if p["status"] == "INSPECTED"), "",
         "Read-only, in memory: absolute paths, `..`, links and devices are skipped and counted (all 14 archives: 0 unsafe members); nothing is extracted or executed.", "",
         "| package | identity | version | kind | sourcetypes defined | ingestion mechanism |", "|---|---|---|---|---|---|"]
    mech = {"splunk_app_stream_ipfix_cisco_hsl": "Splunk App for Stream IPFIX template; no sourcetypes", "aristanetworks": "syslog, sFlow, saved searches", "Splunk_TA_cisco_meraki": "REST modular inputs",
            "Splunk_TA_Cisco_Intersight": "REST modular inputs", "ta_cisco_thousandeyes": "ThousandEyes streams to HEC plus API inputs", "TA_cisco_catalyst": "syslog and REST modular inputs", "TA-cisco-cloud-security-addon": "modular inputs",
            "CiscoSecurityCloud": "modular inputs and syslog", "Splunk_TA_paloalto_networks": "syslog CSV and modular inputs"}
    for p in inv["packages"]:
        a = p["apps"][0]
        L.append("| %s | %s (%s) | %s | %s | %d | %s |" % (p["package"], a["id"], a["label"], a["version"], "; ".join(c.split(" (")[0] for c in a["classification"]), len(a["sourcetypes"]), mech.get(a["id"], "syslog / file (operator chooses)")))
    L += ["", "No package defines a metric schema (`METRIC-SCHEMA-TRANSFORMS`) or a metric index.", "",
          "## 2. Add-on-defined sourcetypes and NetSpout mapping",
          "- %d add-on-defined sourcetype rows (%d distinct names; some names are defined by more than one package, for example `cisco:asa`)." % (len(rows), len(uniq)),
          "- Statuses (rows): %s." % ", ".join("%s %d" % kv for kv in reg["summary"]["by_status"].items()),
          "- Exact name matches with the 349-entry catalog: %d rows; near-name candidates: %d. A name in `props.conf` does not mean NetSpout supports it: %d rows are UNSUPPORTED." % (reg["summary"]["exact_matches"], reg["summary"]["near_matches"], reg["summary"]["by_status"]["UNSUPPORTED"]),
          "- Catalog entries (349): %s." % ", ".join("%s %d" % kv for kv in reg["summary"]["catalog"].items()), "",
          "## 3. Live Splunk verification (isolated TA-validation lab, Splunk 10.2.7)", "", "| sourcetype | add-on | live checks (pass / fail / not run) | before the ownership fix | events verified |", "|---|---|---|---|---|"]
    before = {"cisco:asa": "docs/verification/evidence/ta_compat/cisco_asa_ta_compat_before_fix.json", "fortigate_traffic": "docs/verification/evidence/ta_compat/fortigate_traffic_before_fix.json",
              "pan:traffic": "docs/verification/evidence/ta_compat/pan_traffic_before_fix.json", "cisco:ios": "docs/verification/evidence/ta_compat/cisco_ios_before_fix.json"}
    for st, r in live.items():
        b = load(before[st])["summary"]
        spec = load(r["spec"])
        s = r["summary"]
        L.append("| `%s` | %s %s | %d / %d / %d | %d failed (%d passed) | %s |" % (st, r["package"].split("_")[0], r["version"], s["PASS"], s["FAIL"], s["NOT_RUN"], b["FAIL"], b["PASS"], ", ".join(e["id"] for e in spec["events"])))
    L += ["", "NOT_RUN entries are offline-only checks the add-on cannot support (no routing transform or no `TIME_FORMAT`), never silently passed. Scope: the representative events above, not every message type of the sourcetype.", "",
          "Lab hygiene: each add-on was installed alone, tested and removed (`scripts/lab_ta.py`); the lab ended with the same four apps it started with (netspout, Splunk_TA_cisco-asa, Splunk_TA_microsoft_sysmon, Splunk_TA_windows). Installing all 14 together was not done; the only configuration overlap among the four tested add-ons is one shared transform name (`extract_url_domain`) in Fortinet and Palo Alto, which never coexisted in the lab.", "",
          "## 4. Field ownership (see telemetry_dispatcher.py)",
          "- Proven in the four live runs: an indexed field with the same name as a CIM field hides the add-on's value (ASA: action/src_ip/dest_ip/vendor_action; FortiGate: vendor_action/action/signature; Palo Alto: src_ip/dest_ip/vendor_action/action; IOS: NetSpout values in action/signature/src_ip/dest_ip/protocol).",
          "- Policy: every event carries `netspout_%s` copies; sourcetypes with live-verified add-on parsing (%s) send no bare names. Run and scenario correlation (`netspout_run_id`, `netspout_scenario_id`, ...) is unchanged." % ("{action,signature,status,src_ip,dest_ip,protocol,vendor,node_type}", ", ".join(sorted(live))),
          "- Downstream dependency assessed: three searches in each of the 224 contract dashboards read NetSpout's own status/action/signature; they now read `coalesce(netspout_x, x)` (447 changed searches, 0 parser errors in Splunk). Old searches on TA-owned data returned **0** ASA events; the new ones return all of them.",
          "- Other sourcetypes (%d exact-name matches with a generator) keep the bare names until each is verified." % mm["summary"]["exact_name_matches_with_generator_not_yet_live_verified"], "",
          "## 5. ASA-containing contracts (`docs/verification/evidence/ta_compat/asa_contract_dashboards.json`)"]
    c = load("docs/verification/evidence/ta_compat/asa_contract_dashboards.json")
    for cid, r in c.items():
        L.append("- `%s`: generated %d, HEC accepted %d, indexed %d; %d searches, search errors: %d; changed searches rows (new searches on TA-owned data / on legacy data / old searches): %s." % (
            cid, r["arm_A_current"]["generated"], r["arm_A_current"]["hec_accepted"], r["arm_A_current"]["indexed"], r["searches"], len(r["errors"]),
            {k: (r["rows_new_searches_on_TA_owned_data"][k]["rows"], r["rows_new_searches_on_legacy_data"][k]["rows"], r["rows_old_searches_on_TA_owned_data"][k]["rows"]) for k in r["changed_searches"]}))
    L += ["", "## 6. Specialized telemetry and protocols (not forced through log replay)", "", "| package | expected ingestion | NetSpout gap |", "|---|---|---|"] + ["| %s | %s | %s |" % (p["package_id"], p["expected_ingestion"], p["netspout_gap"]) for p in mm["protocol_gaps"]] + [
          "", "Metric findings: no package defines a metric index or schema. NetSpout labels `cisco:thousandeyes:metric` and `cisco:intersight:metrics` as metric-index payloads, but the add-ons define them as JSON **event** sourcetypes (routing conflict, P1). `cisco:ios:mdt:metric` is not defined by any of the 14 packages (its catalog TA, Splunk Add-on for Cisco IOS, is not among them); its HEC metric payload encoding is covered by unit tests (Phase 1); no `mstats` verification was run in Phase 4.", "",
          "## 7. Unsupported and unverified",
          "- UNSUPPORTED: %d add-on sourcetype rows have no NetSpout implementation; %d catalog entries claim an add-on none of the 14 packages defines." % (reg["summary"]["by_status"]["UNSUPPORTED"], reg["summary"]["catalog"]["CLAIMS_TA_BUT_NOT_DEFINED_IN_DOWNLOADED_PACKAGES"]),
          "- UNVERIFIED (generator exists, never run against its add-on): %d exact-name sourcetypes (list in `ta_mismatch_report.json`)." % mm["summary"]["exact_name_matches_with_generator_not_yet_live_verified"],
          "- Packages with no live test: NetFlow (IPFIX template), Arista, Intersight, Meraki, ThousandEyes, Secure Access, Security Cloud (except the ASA sourcetype it shares), ESA, WSA, Juniper.", "",
          "Prioritized correction plan: `docs/contracts/ta_mismatch_report.md` (migration approach and remediation order)."]
    (EV / "ta_compat/PHASE4_REPORT.md").write_text("\n".join(L) + "\n")
    print("written", len(L), "lines")


if __name__ == "__main__":
    main()
